//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDSTF05936.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//초기화
scwin.fn_init = function() {
    var dateTmp = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(cmb_month1, dateTmp.substring(4, 6));
    $c.stf.setObjectValue(cmb_month2, dateTmp.substring(4, 6));
    $c.stf.setObjectValue(cmb_month3, dateTmp.substring(4, 6));

    //기준년 (콤보박스)
    var urlYear = "/ElwNcr.do?method=selectElwNcrYear&inputMessageId=ELW_NCR_YEAR_INOUT";
    dts_year1.DataID = encodeURI(urlYear);
    dts_year1.reset();
    dts_year2.DataID = encodeURI(urlYear);
    dts_year2.reset();
    dts_year3.DataID = encodeURI(urlYear);
    dts_year3.reset();

    /*dts_inst.DataID = "/etn/EtnCodeAct.do?method=listIsurCd&For=R";
    dts_inst.Reset();*/

    dts_inst.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_inst.Reset();
    dts_lp.DataID = "/CodeAction.do?method=listLeadCom&For=R";
    dts_lp.Reset();

    /*dts_lp.DataID = "/etn/EtnCodeAct.do?method=listLPCd&For=R";
    dts_lp.Reset();*/

    /*dts_LpMbrNo.DataID = "/CodeAction.do?method=listLeadCom&For=R"; 
    dts_LpMbrNo.Reset(); */

    cmb_inst_lp.ComboDataID = "dts_inst";
    scwin.fn_change_gubun("1");
};


//데이타 가져와서 뿌리기 List
scwin.fn_list_sync = function() {
    var url = "/ElwNcr.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchIsurLpNcrDetailList";
    url += "&inputMessageId=ELW_LP_NCR_INOUT&outputMessageId=ELW_LP_NCR_INOUT";
    if (rdo_gubun.getValue() == "1") {
        if (cmb_instlp_select1.BindColVal == "01") url += "&GUBUN=isur";

        else url += "&GUBUN=lp";
        url += "&FROM_YYMM=" + cmb_year1.BindColVal + cmb_month1.BindColVal;
        $c.cm.setColumnProp(grid_list, 'NCR_PRE1', 'Show', true);
        $c.cm.setColumnProp(grid_list, 'NCR_PRE2', 'Show', true);
    } else {
        if (cmb_instlp_select2.BindColVal == "01") url += "&GUBUN=isur";

        else url += "&GUBUN=lp";
        url += "&FROM_YYMM=" + cmb_year2.BindColVal + cmb_month2.BindColVal;
        url += "&TO_YYMM=" + cmb_year3.BindColVal + cmb_month3.BindColVal;
        url += "&ISUR_LP_CD=" + cmb_inst_lp.BindColVal;
        $c.cm.setColumnProp(grid_list, 'NCR_PRE1', 'Show', false);
        $c.cm.setColumnProp(grid_list, 'NCR_PRE2', 'Show', false);
    }
    dts_list.DataID = encodeURI(url);
    dts_list.reset();
    $c.cm.ShowWin(grid_list);
};
scwin.fn_change_gubun = function(gubun) {
    if (gubun == "1") {
        cmb_instlp_select1.setDisabled(true);
        cmb_year1.setDisabled(true);
        cmb_month1.setDisabled(true);
        cmb_instlp_select2.setDisabled(true);
        cmb_inst_lp.setDisabled(true);
        cmb_year2.setDisabled(true);
        cmb_month2.setDisabled(true);
        cmb_year3.setDisabled(true);
        cmb_month3.setDisabled(true);
    } else if (gubun == "2") {
        cmb_instlp_select1.setDisabled(true);
        cmb_year1.setDisabled(true);
        cmb_month1.setDisabled(true);
        cmb_instlp_select2.setDisabled(true);
        cmb_inst_lp.setDisabled(true);
        cmb_year2.setDisabled(true);
        cmb_month2.setDisabled(true);
        cmb_year3.setDisabled(true);
        cmb_month3.setDisabled(true);
    }
};




//엑셀 다운로드
scwin.fn_ExcelDown = function() {
    $c.data.downloadGridViewExcel(grid_list, "ELW LP (영업용)순자본비율", "", "8");
};
scwin.rdo_gubun_OnSelChange = function() {
    scwin.fn_change_gubun(rdo_gubun.getValue());
};
scwin.cmb_instlp_select2_OnSelChange = function() {
    if (cmb_instlp_select2.BindColVal == "01") {
        cmb_inst_lp.ComboDataID = "dts_inst";
    } else if (cmb_instlp_select2.BindColVal == "02") {
        cmb_inst_lp.ComboDataID = "dts_lp";
    } else {
        $c.win.alert(cmb_instlp_select2.BindColVal);
    }
    cmb_inst_lp.setSelectedIndex(0);
};
scwin.dts_year1_OnLoadError = function() {
    $c.stf.alert_error(dts_Year1);
};
scwin.dts_year2_OnLoadError = function() {
    $c.stf.alert_error(dts_Year2);
};
scwin.dts_year3_OnLoadError = function() {
    $c.stf.alert_error(dts_Year3);
};
scwin.dts_list_OnLoadError = function() {
    $c.stf.alert_error(dts_list);
};
scwin.dts_list_OnLoadCompleted = function(rowcount) {
    //	FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grid_list);
    //alert("dts_List.CountRow-->"+dts_List.CountRow);

};
scwin.btn_search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    rdo_gubun.setValue("1");
    scwin.fn_init();
    //fn_list_sync();	

};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
